<section class="admin-card"><h2>Create coupon / offer notice</h2><form method="post" class="admin-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Code<input name="code" placeholder="LAUNCH20" required></label><label>Type<select name="discount_type"><option value="percent">Percent</option><option value="fixed">Fixed</option></select></label><label>Value<input type="number" step="0.01" name="discount_value" required></label><label>Expires<input type="date" name="expires_at"></label><label>Usage limit<input type="number" name="usage_limit" value="100"></label><label>Status<select name="status"><option>active</option><option>disabled</option></select></label><button>Create Coupon</button></form></section><section class="admin-card"><h2>Coupons</h2><table class="admin-table"><tr><th>Code</th><th>Type</th><th>Value</th><th>Expires</th><th>Status</th></tr><?php foreach ($coupons as $coupon): ?><tr><td><?= e($coupon['code']) ?></td><td><?= e($coupon['discount_type']) ?></td><td><?= e($coupon['discount_value']) ?></td><td><?= e($coupon['expires_at']) ?></td><td><?= e($coupon['status']) ?></td></tr><?php endforeach; ?></table></section>
